import random
import time

class Virus:
    def __init__(self, name, symptoms, transmission_rate, mortality_rate):
        self.name = name
        self.symptoms = symptoms
        self.transmission_rate = transmission_rate
        self.mortality_rate = mortality_rate

    def infect(self, person):
        if random.random() < self.transmission_rate:
            person.infected_with = self
            print(f"{person} has been infected with {self}!")
        else:
            print(f"{person} has avoided infection with {self}.")

    def kill(self, person):
        if random.random() < self.mortality_rate:
            print(f"{person} has died from {self}.")
            person.is_alive = False
        else:
            print(f"{person} has survived {self}.")

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age
        self.is_alive = True
        self.infected_with = None

    def post(self, platform):
        if self.is_alive:
            print(f"{self} has posted on {platform}.")
            if self.infected_with:
                print(f"{self} is infected with {self.infected_with}.")
        else:
            print(f"{self} has died and cannot post on {platform}.")
            return False
        return True

    def like(self, post):
        if self.is_alive:
            print(f"{self} has liked {post}.")
        else:
            print(f"{self} has died and cannot like {post}.")
        return self.is_alive

    def comment(self, post):
        if self.is_alive:
            print(f"{self} has commented on {post}.")
        else:
            print(f"{self} has died and cannot comment on {post}.")
        return self.is_alive

    def share(self, post):
        if self.is_alive:
            print(f"{self} has shared {post}.")
        else:
            print(f"{self} has died and cannot share {post}.")
        return self.is_alive

    def recover(self):
        if self.infected_with:
            print(f"{self} has recovered from {self.infected_with}.")
            self.infected_with = None
            self.is_alive = True
        else:
            print(f"{self} is not infected.")
            self.is_alive = True
        return self.is_alive

    def die(self):
        if self.is_alive:
            print(f"{self} has died.")
        self.is_alive = False
        return False

def simulate_outbreak(virus, platform, people):
    infected = [person for person in people if person.infected_with == virus]
    while infected:
        person = infected.pop(0)
        person.post(platform)
        if person.infected_with:
            person.infected_with.kill(person)
        person.infected_with.infect(person)
        if not person.die():
            person.comment(platform)
            person.share(platform)
            person.like(random.choice([post for post in platform if post.author!= person])))
        infected.extend([person for person in people if person.is_alive and person.infected_with == virus and not person.infected_with == person.infected_with])
    print(f"The {virus} outbreak has ended. {len([person for person in people if person.is_alive])} people are still alive.")

def main():
    platform = [Person(f"Post {i}", 20) for i in range(1, 11)]
    people = [Person(f"Person {i}", random.randint(18, 65)) for i in range(1, 11)]
    virus = Virus("Covid-19", "fever", 0.5, 0.2)
    simulate_outbreak(virus, platform, people)

if __name__ == "__main__":
    main()
